# Change the sheet's clerk limit and/or floor. Validate first so a bad value is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.settings.ValidateSettings
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves (the floor moves dues).
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.settings.SaveSettings
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.settings.RecordSettingChanged
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.settings.RespondWithSettings
  govern: [ transaction ]
EOF

